function getPath(obj,path){return path.split('.').reduce((value,key)=>value?.[key],obj);}
function setPath(obj,path,value){const keys=path.split('.');let current=obj;for(const key of keys.slice(0,-1)){if(!current[key]||typeof current[key]!=='object')current[key]={};current=current[key];}current[keys.at(-1)]=value;}
function friendlyDate(value){return value?new Date(value).toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Not published yet';}
function compactDate(value){return new Date(value).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});}
function active(o){const t=Date.now();return o.enabled&&(!o.startAt||Date.parse(o.startAt)<=t)&&(!o.endAt||Date.parse(o.endAt)>t);}
function offerStatus(o){return !o.enabled?'Paused':o.endAt&&Date.parse(o.endAt)<=Date.now()?'Ended':o.startAt&&Date.parse(o.startAt)>Date.now()?'Scheduled':'Active';}
function toast(message){const el=$('#admin-toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('visible'),4500);}
async function api(path,options={}){
 const headers={...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})};
 const response=await fetch(path,{...options,headers,credentials:'same-origin',cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('The studio service is unavailable. Please try again.');}
 if(!response.ok)throw Object.assign(new Error(data.error||'The request could not be completed.'),{status:response.status,passwordRequired:!!data.passwordRequired});return data;
}
async function loadWorkspace(){
 try{const data=preview?window.ADMIN_INITIAL_STATE:await api('/api/admin/state');workspace={...data,dirty:false};safeRender();}
 catch(error){if(error.passwordRequired)passwordUnlock();else if(error.status===401||error.status===403)renderLogin(error.status===403);else $('#admin-root').innerHTML=`<div class="error-screen"><div class="admin-eyebrow">Studio control</div><h1>Let’s reconnect.</h1><p>${E(error.message)}</p><button class="admin-button" data-action="reload">Try again ${icon('arrow')}</button> <a class="admin-button secondary" href="/">Visit website</a></div>`;}
}
