function safeRender(){
 try{render()}catch(error){
  console.error('Studio Control recovered from render failure',error);
  const el=$('#admin-root');if(!el)return;
  el.innerHTML='<main class="error-screen" style="max-width:850px;margin:6vh auto;padding:32px"><div class="admin-eyebrow">STUDIO CONTROL / RECOVERY</div><h1>Owner session connected.</h1><p>The site interface failed to load one module, but project data was not changed. Refresh after publishing website assets.</p><button class="admin-button" data-action="reload">Refresh admin ↗</button> <a class="admin-button secondary" href="/admin/#/overview">Studio overview ↗</a></main>';
 }
}
function render(){
 if(!workspace)return;section=location.hash.slice(2)||'command';if(!navigation.some(x=>x[0]===section))section='overview';
 document.title=`${navigation.find(x=>x[0]===section)[1]} — VELORYZ Studio Control`;
 $('#admin-root').innerHTML=`<div class="admin-layout ${section==='client-portal'?'cpm-admin-mode':''}">${sidebar()}<main class="admin-main"><header class="admin-topbar"><div class="breadcrumbs"><button class="mobile-admin-menu" data-action="menu" aria-label="Open admin menu">${icon('menu')}</button><span class="workspace-label">Workspace</span><span class="workspace-label">/</span><strong>${navigation.find(x=>x[0]===section)[1]}</strong></div><div class="topbar-actions"><button type="button" class="ad-search-trigger" data-action="nav-search" aria-label="Search admin consoles (Control K)">${icon('search')}<span>Quick find</span><kbd>⌘K</kbd></button><button class="admin-motion" data-motion-control aria-label="Motion settings"><span class="motion-wave" aria-hidden="true"><i></i><i></i><i></i></span></button><span class="status-label ${workspace.dirty?'unsaved':''}" id="workspace-status">${workspace.dirty?'Unsaved changes':workspace.hasDraft?'Draft changes saved':'All changes published'}</span><a class="admin-button secondary" href="/admin/preview" target="_blank" rel="noopener">${icon('eye')}<span class="preview-label">Preview draft</span></a><button class="admin-button secondary" data-action="save">${icon('save')}<span class="draft-label">Save draft</span></button><button class="admin-button" data-action="publish">${icon('publish')}Publish site</button></div></header>${preview?'<div class="notice-bar">'+icon('info')+'Local design preview. Saving and publishing require the studio password on the deployed website.</div>':''}<div class="admin-content" id="admin-content">${safeConsoleInsights()}${pageContent()}</div></main></div>`;
 if(section==='platform'&&!aiSettings&&!aiSettingsLoading)loadAiSettings();
 if(section==='reviews'&&(!ownerReviews||Date.now()-ownerReviewFetched>45000)&&!ownerReviewLoading)loadOwnerReviews();
 if(section==='ai-control'&&aiHubTab==='assistants'&&!knowledgeAiProfiles&&!knowledgeAiLoading)loadKnowledgeAi();
 if(section==='ai-control'&&aiHubTab==='provider'&&!aiSettings&&!aiSettingsLoading)loadAiSettings();
 if(section==='knowledge-ai'&&!knowledgeAiProfiles&&!knowledgeAiLoading)loadKnowledgeAi();
 if(section==='payments'&&!paymentsLoaded&&!paymentsLoading&&!paymentsError)loadPayments();
 if(section==='enquiries'&&!enquiryLoaded&&!enquiryLoading)loadEnquiries();
  if(section==='client-portal'&&!cpLoaded&&!cpLoading)cpLoad();
 if(section==='media'&&!mediaLoaded)loadMedia();if(section==='history'&&!historyLoaded)loadHistory();
}
