function markDirty(){workspace.dirty=true;const label=$('#workspace-status');if(label){label.textContent='Unsaved changes';label.classList.add('unsaved');}}
async function saveDraft(){
 if(preview){toast('Sign in on the deployed website to save changes.');return false;}
 const result=await api('/api/admin/draft',{method:'PUT',body:JSON.stringify({state:workspace.state,draftVersion:workspace.draftVersion})});workspace.draftVersion=result.draftVersion;workspace.updatedAt=result.updatedAt;workspace.dirty=false;workspace.hasDraft=true;
 const label=$('#workspace-status');if(label){label.textContent='Draft changes saved';label.classList.remove('unsaved');}return true;
}
async function publish(){
 if(busy)return;if(preview){toast('Publishing is available after the owner signs in.');return;}busy=true;updateBusy(true);
 try{if(workspace.dirty)await saveDraft();const data=await api('/api/admin/publish',{method:'POST',body:JSON.stringify({draftVersion:workspace.draftVersion,publishedVersion:workspace.publishedVersion,summary:'Studio website updated'})});workspace.publishedVersion=data.publishedVersion;workspace.updatedAt=data.updatedAt;workspace.hasDraft=false;historyLoaded=false;try{localStorage.setItem('veloryz.publication',String(data.publishedVersion));}catch{}render();toast('Published. Your website now has the latest studio content.');}
 catch(error){toast(error.message);}finally{busy=false;updateBusy(false);}
}
