function updateMediaPreview(path,value,type){const input=$(`[data-media-input="${path}"]`);if(input)input.value=value;const el=$(`[data-media-preview="${path}"]`);if(el)el.innerHTML=value?type==='video'?`<video src="${E(value)}" controls preload="metadata"></video>`:`<img src="${E(value)}" alt="Selected media preview">`:icon(type==='video'?'film':'media');}
async function loadMedia(){if(preview){mediaLoaded=true;mediaItems=[];if(section==='media')render();return;}try{const data=await api('/api/admin/media');mediaItems=data.items;mediaLoaded=true;if(section==='media')render();}catch(error){toast(error.message);}}
async function loadHistory(){if(preview){historyLoaded=true;historyItems=[];if(section==='history')render();return;}try{const data=await api('/api/admin/history');historyItems=data.items;historyLoaded=true;if(section==='history')render();}catch(error){toast(error.message);}}
let mediaCallback=null,mediaFilter='image';
async function chooseMedia(callback,type='image'){
 mediaCallback=callback;mediaFilter=type;if(!mediaLoaded)await loadMedia();
 const items=mediaItems.filter(m=>m.mime.startsWith(type+'/'));
 showModal(type==='video'?'Choose a film.':'Choose an image.','Use an existing asset or upload something new.',`<div style="margin-bottom:20px"><button class="admin-button secondary" data-action="picker-upload">${icon('upload')}Upload ${type}</button></div>${items.length?`<div class="media-grid">${items.map(m=>mediaCard(m,true)).join('')}</div>`:empty(type==='video'?'film':'media','A blank canvas, for now.','Upload a file to begin your studio media collection.','','')}`,`<span class="footer-hint">${type==='video'?'MP4 or WebM up to 25 MB.':'PNG, JPG, WebP, GIF or AVIF up to 8 MB.'}</span><button class="admin-button secondary" data-action="close-modal">Cancel</button>`);
}
function filePrompt(accept,callback){
 const input=document.createElement('input');
 input.type='file';input.accept=accept;input.className='file-input';
 input.setAttribute('aria-label','Choose an image or video to upload');
 document.body.append(input);
 const cleanup=()=>input.remove();
 input.addEventListener('change',()=>{const file=input.files?.[0];cleanup();if(file)callback(file);},{once:true});
 // The click is handled directly from the user's action, preserving browser file-picker permission.
 input.click();
}
async function uploadFile(file,select=false){
 if(preview){toast('Uploads require the live signed-in owner workspace, not a preview.');return;}
 const extension=String(file.name.split('.').pop()||'').toLowerCase();
 const types={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',gif:'image/gif',avif:'image/avif',mp4:'video/mp4',webm:'video/webm'};
 const type=file.type||types[extension]||'';
 if(!Object.values(types).includes(type)){toast('Choose PNG, JPG, WebP, GIF, AVIF, MP4 or WebM.');return;}
 const isVideo=type.startsWith('video/'),limit=(isVideo?25:8)*1024*1024;
 if(!file.size||file.size>limit){toast(isVideo?'Video exceeds 25 MB. Compress the video and try again.':'Image exceeds 8 MB. Resize or compress it and try again.');return;}
 const progress=document.createElement('div');
 progress.className='upload-progress';
 progress.setAttribute('role','status');progress.setAttribute('aria-live','polite');
 progress.textContent='Uploading '+file.name+'…';
 (document.querySelector('.admin-modal-body')||document.querySelector('#upload-state')||document.querySelector('#admin-content')||document.querySelector('.admin-main')||document.body).prepend(progress);
 try{
  const body=new FormData();
  const upload=file.type===type?file:new File([file],file.name,{type,lastModified:file.lastModified});
  body.append('file',upload,upload.name);
  const item=await api('/api/admin/media',{method:'POST',body,signal:AbortSignal.timeout(90000)});
  if(!item?.id||!/^\/media\/[a-z0-9-]+$/i.test(item.url||''))throw new Error('Upload response was incomplete. Refresh Media Library before retrying, to avoid a duplicate.');
  mediaItems.unshift(item);mediaLoaded=true;
  if(select&&mediaCallback){const callback=mediaCallback;mediaCallback=null;closeModal();callback(item.url);}
  else if(section==='media')render();
  toast('Upload saved. '+(select?'Image or video selected — save and publish your changes.':'Choose this asset on a project, campaign, or showcase.'));
 }catch(error){
  const detail=error.name==='TimeoutError'?'Upload timed out. Please check Media Library before trying again.':error.status===413?'This file exceeds the server upload limit.':error.status===503?'Media storage is temporarily unavailable. Check Studio Control → Connections.':error.status===401?'Your admin session expired. Unlock the workspace and retry.':error.message;
  const message='Upload failed: '+detail;
  progress.textContent=message;
  progress.setAttribute('role','alert');
  toast(message);
 }finally{if(progress.getAttribute('role')!=='alert')progress.remove();}
}
function applyProjectFilter(){const query=($('#project-search')?.value||'').toLowerCase(),filter=$('#project-filter')?.value||'all';$$('[data-project-row]').forEach(row=>{const p=workspace.state.projects.find(p=>p.id===row.dataset.projectRow);row.hidden=!p.name.toLowerCase().includes(query)||(filter==='featured'&&!p.featured)||(filter==='visible'&&!p.published)||(filter==='hidden'&&p.published);});}
document.addEventListener('input',event=>{
 const el=event.target;if(el.matches('[data-bind]')){let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.hasAttribute('data-array')?el.value.split('\n').filter(Boolean):el.value;setPath(workspace.state,el.dataset.bind,value);markDirty();}
 if(el.matches('[data-edit]')){let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.hasAttribute('data-array')?el.value.split('\n').filter(Boolean):el.type==='datetime-local'?(el.value?new Date(el.value).toISOString():''):el.value;setPath(editor,el.dataset.edit,value);editorDirty=true;if(el.dataset.edit==='mediaType')$$('[data-path="media"]').forEach(button=>button.dataset.type=value==='video'?'video':'image');if(editorKind==='offer'&&$('#offer-editor-preview'))$('#offer-editor-preview').innerHTML=miniCampaign(editor);}
 if(el.id==='project-search')applyProjectFilter();
});
document.addEventListener('change',event=>{
 const el=event.target;if(el.hasAttribute('data-project-toggle')){const p=workspace.state.projects.find(p=>p.id===el.dataset.id);p[el.dataset.projectToggle]=el.checked;markDirty();}
 if(el.hasAttribute('data-offer-toggle')){workspace.state.offers.find(o=>o.id===el.dataset.offerToggle).enabled=el.checked;markDirty();}
 if(el.id==='enquiry-filter'){enquiryFilter=el.value;enquiryPage=0;enquiryLoaded=false;render();}
 if(el.id==='project-filter')applyProjectFilter();
 if(el.hasAttribute('data-team-projects')){workspace.state.team[Number(el.dataset.teamProjects)].projects=[...el.selectedOptions].map(option=>option.value);markDirty();}
});
document.addEventListener('submit',async event=>{
 if(!event.target.matches('[data-editor-form]'))return;event.preventDefault();if(!event.target.reportValidity())return;
 const submit=event.submitter;if(submit)submit.disabled=true;
 try{
  if(editorKind==='offer'&&editor.startAt&&editor.endAt&&new Date(editor.startAt)>=new Date(editor.endAt))throw new Error('Choose an end time after the start time.');
  const collection=workspace.state[editorKind==='project'?'projects':'offers'],oldIndex=collection.findIndex(item=>item.id===editor.id),oldState=structuredClone(collection);
  if(oldIndex<0)collection.push(structuredClone(editor));else collection[oldIndex]=structuredClone(editor);markDirty();
  try{const saved=await saveDraft();if(!saved&&preview){closeModal();render();toast('Design preview updated. Sign in on the live site to save.');return;}}catch(error){workspace.state[editorKind==='project'?'projects':'offers']=oldState;throw error;}
  closeModal();render();if(submit?.value==='publish'){await publish();return;}toast(editorKind==='project'?'Project saved to draft. Publish when ready.':'Campaign saved to draft. Publish when ready.');
 }catch(error){$('#editor-error').innerHTML=`<div class="dialog-error" role="alert" style="margin-top:20px">${E(error.message)}</div>`;}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action],.admin-modal-backdrop');if(!button)return;
 if(button.classList.contains('admin-modal-backdrop')){if(event.target===button)closeModal();return;}
 const action=button.dataset.action,id=button.dataset.id;
 try{
  if(action==='enquiry-open'){openEnquiry(id);return;}
  if(action==='enquiry-refresh'){enquiryLoaded=false;render();return;}
  if(action==='enquiry-page'){enquiryPage=Math.max(0,enquiryPage+Number(id));enquiryLoaded=false;render();return;}
  if(action==='accept-copy-code'){
   const field=$('#vz-accepted-invite-code');
   if(field){try{await navigator.clipboard.writeText(field.value);toast('Private code copied. Do not share outside the intended recipient.');}catch{field.select();toast('Select and copy this access code securely.');}}
   return;
  }
  if(action==='accept-open-client'){
   closeModal();
   cpSelected=id;
   cpTab='overview';
   location.hash='#/client-portal';
   cpLoaded=false;
   render();
   return;
  }
  if(action==='enquiry-accept'){
   if(preview){toast('This needs the live signed-in owner workspace.');return;}
   const request=enquiryItems.find(x=>x.id===id);
   if(!request)return;
   if(!confirm('Accept the project request for '+request.name+'?\n\nThis creates the private client workspace and prepares the one-page order PDF. NO emails will be sent now. You will send the detailed project summary and separate invitation with two individual buttons in Client Management.'))return;
   button.disabled=true;button.textContent='Accepting project & preparing order…';
   try{
    const result=await api('/api/client-portal/admin/accept',{method:'POST',body:JSON.stringify({enquiry_id:id}),signal:AbortSignal.timeout(100000)});
    closeModal();
    enquiryLoaded=false;cpLoaded=false;
    acceptanceResult(result);
   }finally{button.disabled=false;}
   return;
  }
  if(action==='enquiry-save'){if(preview){toast('Read-only design preview.');return;}const item=enquiryItems.find(x=>x.id===id);button.disabled=true;try{await api('/api/admin/enquiries/'+id,{method:'PUT',body:JSON.stringify({status:$('#enquiry-status').value,notes:$('#enquiry-notes').value,version:item.version})});closeModal();enquiryLoaded=false;render();toast('Enquiry updated. Send your reply using your contact app.');}finally{button.disabled=false;}return;}
  if(action==='content-audit'){
   if(preview){toast('The content review requires the owner workspace.');return;}
   const report=await api('/api/admin/quality');
   const entries=report.issues.map(issue=>`<li style="margin:12px 0;font-size:13px;line-height:1.6"><strong>${E(issue.severity.toUpperCase())} · ${E(issue.area)}</strong><div>${E(issue.message)}</div></li>`).join('');
   showModal('Website content review','Source-data checks before publishing. External URLs, browser accessibility and live APIs still need separate verification.',`<p role="status">${report.ok?'No blocking data defects.':'Blocking data defects detected.'} ${report.count} review finding(s).</p><ul style="padding-left:20px;margin-top:15px">${entries}</ul>`,`<button type="button" class="admin-button" data-action="close-modal">Close</button>`,'medium');
   return;
  }
  if(action==='reload'){await loadWorkspace();return;}
  if(action==='reload-media'){mediaLoaded=false;mediaItems=[];await loadMedia();return;}
  if(action==='run-health'){await runAdminDiagnostics();return;}
  if(action==='nav-search'){window.VeloryzAdminDetail?.openSearch(showModal,navigation,E);return;}
  if(action==='menu'){$('.sidebar').classList.toggle('open');return;}
  if(action==='close-menu'){$('.sidebar').classList.remove('open');return;}
  if(action==='close-modal'){closeModal();return;}
  if(action==='confirm-action'||action==='confirm-publish'){const callback=confirmAction.callback;closeModal();await callback?.();if(action==='confirm-publish')await publish();return;}
  if(action==='save'){if(busy)return;busy=true;updateBusy(true);try{if(await saveDraft())toast('Draft saved. Your live website is unchanged.');}finally{busy=false;updateBusy(false);}return;}
  if(action==='publish'){await publish();return;}
  if(action==='new-project'||action==='edit-project'){openProject(id);return;}
  if(action==='delete-project'){confirmAction('Remove this project?','It will be removed from your draft. Publish the site to apply the change.',async()=>{workspace.state.projects=workspace.state.projects.filter(p=>p.id!==id);markDirty();render();},'Remove from draft',true);return;}
  if(action==='new-offer'||action==='edit-offer'){openOfferEditor(id,button.dataset.kind||'offer',button.dataset.placement||'popup');return;}
  if(action==='duplicate-offer'){const source=workspace.state.offers.find(o=>o.id===id);workspace.state.offers.push({...structuredClone(source),id:'campaign-'+newItemId(),title:source.title+' (copy)',enabled:false});markDirty();render();toast('Campaign duplicated as a paused draft.');return;}
  if(action==='preview-offer'){const offer=workspace.state.offers.find(o=>o.id===id);showModal('A considered entrance.','Campaign preview · '+offerStatus(offer),miniCampaign(offer)+`<div class="offer-timing-note">Your draft preview shows the chosen popup, in-page, or pinned placement. Logos, links and motion use the same public design components.</div>`,`<button class="admin-button secondary" data-action="close-modal">Close preview</button>`,'medium');return;}
  if(action==='delete-offer'){confirmAction('Remove this campaign?','The campaign will leave your draft. Publish to remove it from the live website.',()=>{workspace.state.offers=workspace.state.offers.filter(o=>o.id!==id);markDirty();render();},'Remove from draft',true);return;}
  if(action==='content-tab'){contentTab=id;render();return;}
  if(action==='new-service'){workspace.state.services.push({name:'New service',short:'',description:'',deliverables:'',tags:[]});markDirty();render();return;}
  if(action==='new-team'){workspace.state.team.push({name:'New team member',initials:'',role:'',description:'',slug:'new-team-'+Date.now(),specialties:[],experience:[],experienceIsSample:true,avatar:'',projects:[]});markDirty();render();return;}
  if(action==='remove-service'||action==='remove-team'){const key=action==='remove-service'?'services':'team';confirmAction('Remove this entry?','This removes the entry from your draft. Publish to apply the change.',()=>{workspace.state[key].splice(Number(id),1);markDirty();render();},'Remove from draft',true);return;}
  if(action==='choose-logo'){await chooseMedia(value=>{workspace.state.branding[id]=value;markDirty();render();},'image');return;}
  if(action==='reset-logo'){workspace.state.branding[id]='';markDirty();render();return;}
  if(action==='choose-editor-media'){const {path,context,type}=button.dataset;await chooseMedia(value=>{setPath(context==='editor'?editor:workspace.state,path,value);if(context==='editor')editorDirty=true;else markDirty();updateMediaPreview(path,value,type);},type);return;}
  if(action==='clear-editor-media'){const {path,context,type}=button.dataset;setPath(context==='editor'?editor:workspace.state,path,'');if(context==='editor')editorDirty=true;else markDirty();updateMediaPreview(path,'',type);return;}
  if(action==='pick-media'){const item=mediaItems.find(m=>m.id===id),callback=mediaCallback;closeModal();callback?.(item.url);return;}
  if(action==='upload'||action==='picker-upload'){filePrompt(action==='picker-upload'?mediaFilter==='image'?'image/png,image/jpeg,image/webp,image/gif,image/avif':'video/mp4,video/webm':'image/png,image/jpeg,image/webp,image/gif,image/avif,video/mp4,video/webm',file=>uploadFile(file,action==='picker-upload'));return;}
  if(action==='copy-media'){const item=mediaItems.find(m=>m.id===id);try{await navigator.clipboard.writeText(location.origin+item.url);toast('Media link copied.');}catch{showModal('Your media link.','Copy this link to reuse the file.',`<input style="width:100%;padding:12px;border:1px solid #dce5d1" readonly value="${E(location.origin+item.url)}">`,'','small');}return;}
  if(action==='archive-media'){confirmAction('Archive this asset?','It will leave the media library. Existing website references and saved versions will keep working.',async()=>{await api('/api/admin/media/'+id,{method:'DELETE'});mediaItems=mediaItems.filter(m=>m.id!==id);render();toast('Asset archived.');},'Archive asset');return;}
  if(action==='restore'){confirmAction('Return to this chapter?','This version will replace your draft. The current live site stays in place until you publish.',async()=>{const data=await api('/api/admin/restore',{method:'POST',body:JSON.stringify({id,draftVersion:workspace.draftVersion})});workspace={...data,dirty:false};safeRender();toast('Version restored to draft. Preview, then publish when ready.');},'Restore to draft');return;}
  if(action==='discard'){confirmAction('Discard your draft changes?','Your draft will return to the current published version.',async()=>{const data=await api('/api/admin/discard',{method:'POST',body:JSON.stringify({draftVersion:workspace.draftVersion})});workspace={...data,dirty:false};safeRender();toast('Draft reset to the published version.');},'Discard draft');return;}
  if(action==='export'){const blob=new Blob([JSON.stringify({format:'veloryz-studio-v1',state:workspace.state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='veloryz-studio-content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(action==='import'){filePrompt('application/json,.json',async file=>{try{const data=JSON.parse(await file.text());if(data.format!=='veloryz-studio-v1'||!data.state)throw new Error('Choose a VELORYZ Studio content backup.');confirmAction('Bring this content into the studio?','The imported document will replace your draft. It will not change the published website until you publish.',async()=>{const before=workspace.state;workspace.state=data.state;try{if(await saveDraft()){render();toast('Content imported to draft.');}}catch(error){workspace.state=before;toast(error.message);}},'Import to draft');}catch(error){toast(error.message);}});return;}
 }catch(error){toast(error.message);}
});
document.addEventListener('keydown',event=>{
 const modal=$('.admin-modal');
 if(workspace&&!modal&&((event.key.toLowerCase()==='k'&&(event.ctrlKey||event.metaKey))||(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.target.closest('input,textarea,select,[contenteditable="true"]')))){event.preventDefault();window.VeloryzAdminDetail?.openSearch(showModal,navigation,E);return;}if(event.key==='Escape'){if(modal)closeModal();else $('.sidebar')?.classList.remove('open');}
 if(event.key==='Tab'&&modal){const items=$$('a[href],button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),video[controls]',modal).filter(el=>el.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}
 if((event.ctrlKey||event.metaKey)&&event.key==='s'){event.preventDefault();if(workspace&&!busy)saveDraft().then(saved=>saved&&toast('Draft saved.')).catch(error=>toast(error.message));}
});
