function mailboxContentEditor(){return `<section class="form-card"><div class="form-card-header"><div><h2>A little note, a lot of personality.</h2><p>This message appears as an animated letter beside the tiny mailbox at the bottom of every public page.</p></div></div><div class="admin-form-grid"><label class="toggle" style="grid-column:1/-1"><input type="checkbox" data-bind="site.mailboxEnabled" ${workspace.state.site.mailboxEnabled!==false?'checked':''}>Show the founder’s mailbox</label>${field('Letter title','site.mailboxTitle',{full:true,max:160})}${field('Your note','site.mailboxMessage',{textarea:true,full:true,max:5000,help:'Line breaks are preserved. Keep it personal; this is a little note from your desk.'})}</div></section>`;}

function newItemId(){return crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12);}

async function loadEnquiries(){
 const sequence=++enquirySequence;enquiryLoading=true;enquiryError='';
 try{
  let data;
  if(preview){const day=new Date(Date.now()+86400000).toISOString().slice(0,10);data={total:1,items:[{id:'00000000-0000-4000-8000-000000000001',reference:'VZ-PREVIEW',name:'Preview Visitor',email:'visitor@example.com',phone:'',service:'Websites & development',budget:'Let’s discuss',preferred_date:day,preferred_time:'11:00 AM – 12:00 PM',company:'Example studio',message:'A sample enquiry to preview the inbox design. No real request or message was sent.',status:'new',notes:'',version:0,created_at:new Date().toISOString(),updated_at:new Date().toISOString()}]};}
  else data=await api('/api/admin/enquiries?status='+encodeURIComponent(enquiryFilter)+'&page='+enquiryPage);
  if(sequence!==enquirySequence)return;enquiryItems=data.items;enquiryTotal=data.total;enquiryLoaded=true;
 }catch(error){if(sequence!==enquirySequence)return;enquiryError=error.message;enquiryLoaded=true;}
 finally{if(sequence===enquirySequence){enquiryLoading=false;if(section==='enquiries')render();}}
}
function requestNeedsFollowup(item){
 if(item.status!=='new')return false;
 const started=Date.parse(item.created_at||'');
 return Number.isFinite(started)&&Date.now()-started>=12*3600000;
}
function enquiriesPage(){return `${heading('Studio operations','Project console','Review design requests, project briefs, customer details and payment discussions.')}<section class="admin-panel"><div class="panel-header"><div><h2>Customer requests</h2><p>Confidential requests, accessible only in the authorized studio workspace. New requests older than 12 hours are marked for follow-up.</p></div><button class="admin-button secondary" data-action="enquiry-refresh">Refresh ↻</button></div><div class="enquiry-toolbar"><label for="enquiry-filter">Show requests</label><select id="enquiry-filter">${['all','new','contacted','confirmed','closed'].map(status=>`<option ${status===enquiryFilter?'selected':''} value="${status}">${status==='all'?'All requests':status[0].toUpperCase()+status.slice(1)}</option>`).join('')}</select><span>${enquiryTotal} request${enquiryTotal===1?'':'s'}</span></div>${enquiryError?`<p class="enquiry-empty" role="alert">${E(enquiryError)} Use Refresh to retry.</p>`:!enquiryLoaded?'<p class="enquiry-empty" role="status">Loading your conversations…</p>':!enquiryItems.length?'<p class="enquiry-empty">A little quiet, for now. New consultation requests will appear here.</p>':`<div class="enquiry-list">${enquiryItems.map(item=>`<button class="enquiry-row" data-action="enquiry-open" data-id="${E(item.id)}"><span class="enquiry-avatar">${E(item.name.slice(0,1))}</span><span class="enquiry-person"><strong>${E(item.name)}</strong><small>${E(item.service)}</small></span><span class="enquiry-schedule">${E(item.preferred_date||item.reference)}<small>${E(item.preferred_time?item.preferred_time+' · IST':item.email)}</small></span><span class="pill ${item.status==='closed'?'gray':''}">${requestNeedsFollowup(item)?'Follow up · 12h+':E(item.status)}</span><span class="enquiry-arrow">↗</span></button>`).join('')}</div>`}<div class="enquiry-pagination"><button class="admin-button secondary" data-action="enquiry-page" data-id="-1" ${enquiryPage===0?'disabled':''}>← Previous</button><span>Page ${enquiryPage+1}</span><button class="admin-button secondary" data-action="enquiry-page" data-id="1" ${(enquiryPage+1)*25>=enquiryTotal?'disabled':''}>Next →</button></div></section>`;}
function parseCreatorV3(message){
 if(!/^PROJECT CREATOR V[34](?:\n|$)/.test(String(message||'')))return null;
 const fields=Object.create(null);
 for(const line of String(message).split('\n').slice(1,35)){
  const at=line.indexOf(': ');if(at<1)continue;
  const key=line.slice(0,at).trim(),value=line.slice(at+2).trim();
  if(key&&value)fields[key]=value;
 }
 return fields;
}
function creatorBriefPanel(message){
 const data=parseCreatorV3(message);if(!data)return '';
 const keys=[['Project','PROJECT'],['Template','STARTER'],['Visual style','DESIGN DIRECTION'],['Pages / screens','PAGES / SCREENS'],['Features','SELECTED CAPABILITIES'],['Materials','MATERIALS READY'],['Budget preference','PREFERRED BUDGET'],['Indicative range','PRELIMINARY RANGE'],['Timeline','LAUNCH WINDOW'],['Priority','MAIN PRIORITY']];
 return '<section class="creator-request-panel"><div class="creator-request-heading"><span>✳ &nbsp; PROJECT CREATOR</span><h3>The project, clearly defined.</h3><p>This is a planning brief from the client—not an approved quotation or confirmed project.</p></div>'+
  '<div class="creator-request-fields">'+keys.filter(([key])=>data[key]).map(([key,label])=>'<div><span>'+E(label)+'</span><strong>'+E(data[key])+'</strong></div>').join('')+'</div>'+
  (data.Goal?'<div class="creator-request-goal"><span>WHAT THE CLIENT WANTS TO ACHIEVE</span><p>'+E(data.Goal)+'</p></div>':'')+
  (data['External inspiration']?'<p class="creator-request-extra">External reference: '+E(data['External inspiration'])+'</p>':'')+
  '<p class="creator-request-small">See the original enquiry below for feature-specific requirements, notes and any additional details.</p></section>';
}

function acceptanceResult(result){
 const project=result.project||{},pid=String(result.id||project.id||'');
 const statuses=[
  {label:'Project accepted & workspace created',text:'The original enquiry is safely linked to one private client workspace.',done:true},
  {label:'Industrial one-page project PDF',text:'The order summary is ready to download. The complete original brief is retained with the client project.',done:true},
  {label:'Send detailed order-summary email',text:'Open Client Management and click Send Project Summary to attach and deliver the PDF.',done:false},
  {label:'Issue private client invitation',text:'Separately click Send Client Invitation to generate and email the single-use access code.',done:false}
 ];
 const html='<section class="vz-accepted"><div class="vz-accepted-heading"><span>VELORYZ / ORDER ACCEPTANCE</span>'+
  '<h2>'+E(project.title||'Client project')+'</h2><p>'+E(project.client_name||'')+' · '+E(project.client_email||'')+'</p></div>'+
  '<div class="vz-accept-ref"><strong>'+E(project.request_reference||result.reference||'VELORYZ PROJECT')+'</strong><small>Official project reference</small></div>'+
  '<div class="vz-accept-timeline">'+statuses.map((x,i)=>'<div class="vz-accept-step"><span class="vz-accept-step-dot '+(x.done?'is-ok':'is-review')+'">'+(i+1)+'</span>'+
   '<div><strong>'+E(x.label)+'</strong><p>'+E(x.text)+'</p></div><small>'+(x.done?'Ready':'Owner action needed')+'</small></div>').join('')+'</div>'+
  '<p class="vz-accept-existing">No email or private access code is generated by accepting alone. Each email is sent only when the owner explicitly clicks its individual button in Client Management.</p></section>';
 const pdf='/api/client-portal/admin/projects/'+encodeURIComponent(pid)+'/summary';
 showModal(result.already_accepted?'Project already accepted':'Project accepted · ready for email handoff',
  'The client workspace and order summary are ready. The client has not been emailed or invited by this action.',
  html,'<a href="'+E(pdf)+'" class="admin-button secondary" target="_blank" rel="noopener">Preview one-page order PDF ↓</a>'+
  '<button type="button" class="admin-button" data-action="accept-open-client" data-id="'+E(pid)+'">Open Client Management →</button>'+
  '<button type="button" class="admin-button secondary" data-action="close-modal">Close</button>','medium');
}

function openEnquiry(id){
 const item=enquiryItems.find(x=>x.id===id);if(!item)return;
 const subject=(item.status==='confirmed'?'Consultation confirmation':'Your studio enquiry')+' · '+item.reference;
 const message=`Hi ${item.name},\n\nThank you for your enquiry (${item.reference}).\nPreferred consultation: ${item.preferred_date}, ${item.preferred_time} IST.\n\n${item.status==='confirmed'?'Your consultation time is confirmed.':'Let’s discuss the next step for your project.'}\n\nVELORYZ Studio`;
 const email='mailto:'+encodeURIComponent(item.email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
 const phone=item.phone.replace(/\D/g,'');
 showModal(E(item.name),E(item.reference)+' · Received '+E(friendlyDate(item.created_at)),`<div class="enquiry-detail-grid"><div><span>Email</span><a href="mailto:${E(item.email)}">${E(item.email)}</a></div><div><span>Phone / WhatsApp</span><strong>${E(item.phone||'Not provided')}</strong></div><div><span>Service</span><strong>${E(item.service)}</strong></div><div><span>Budget</span><strong>${E(item.budget||'Let’s discuss')}</strong></div><div><span>Preferred consultation · IST</span><strong>${E(item.preferred_date||'To be arranged')}<br>${E(item.preferred_time)}</strong></div><div><span>Company / website</span><strong>${E(item.company||'Not provided')}</strong></div></div>${creatorBriefPanel(item.message)}<div class="enquiry-message"><span>THE FULL PROJECT SPECIFICATION</span><p>${E(item.message).replace(/\n/g,'<br>')}</p></div><section data-request-history><h3>Request activity</h3><p>Loading activity…</p></section><div class="enquiry-edit"><label for="enquiry-status">Request status</label><select id="enquiry-status">${['new','contacted','confirmed','closed'].map(status=>`<option ${status===item.status?'selected':''} value="${status}">${status}</option>`).join('')}</select><label for="enquiry-notes">Private studio notes</label><textarea id="enquiry-notes" maxlength="3000" rows="4">${E(item.notes)}</textarea><p>Confirming reserves the preferred time and prevents a second confirmation for that slot. Send your reply separately using the contact drafts below.</p></div><div class="enquiry-reply"><a class="admin-button secondary" href="${E(email)}">Prepare email reply ↗</a>${phone?`<a class="admin-button secondary" href="https://wa.me/${phone}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">Prepare WhatsApp reply ↗</a>`:''}</div>`,`<span class="footer-hint">Changes apply to this inbox immediately.</span><button class="admin-button vz-accept-trigger" data-action="enquiry-accept" data-id="${E(id)}">✓ Accept &amp; onboard client</button><button class="admin-button secondary" data-cpm="from-enquiry" data-id="${E(id)}">Create manually ↗</button><button class="admin-button secondary" data-action="enquiry-save" data-id="${E(id)}">Save notes ${icon('check')}</button>`);
 const history=document.querySelector('[data-request-history]');
 api('/api/admin/enquiries/'+encodeURIComponent(id)+'/activity').then(({events})=>{
  if(!history.isConnected)return;
  history.innerHTML='<h3>Request activity</h3>'+events.map(e=>'<p><strong>'+E(e.status)+'</strong> · '+E(new Date(e.recorded_at).toLocaleString('en-IN'))+'<br>'+E(e.notes||'Request received')+'</p>').join('');
 }).catch(()=>{history.querySelector('p').textContent='Activity could not be loaded.';});
}

document.addEventListener('click',event=>{const b=event.target.closest('[data-broadcast-filter]');if(b){campaignFilter=b.dataset.broadcastFilter;render();}});
